import std.concurrent as conc

pub type AppError = Failed(String)

record Config { keep: Int64 }

pub fn main() -> Result<(), AppError> {
    let counter = conc.Mutex(0)
    let next = counter.update(|v| v + 1)
    let seen = counter.get()
    counter.set(5)
    let ready = conc.Atomic(true)
    ready.set(false)
    let cfg = conc.AtomicRef(Config { keep: 1 })
    let text = "abc"
    let cache = conc.RwLock(text)
    let upper = cache.read(|s| s)
    let a = conc.Mutex(0)
    let b = conc.Mutex(0)
    let good = a.update(|x| x + b.get())
    let _ = next
    let _ = seen
    let _ = cfg
    let _ = upper
    let _ = good
    return Ok(())
}

